package com.bettercontent.tests.suite.repositories

import com.bettercontent.tests.Hashes
import com.bettercontent.tests.suite.BoundFile
import com.bettercontent.tests.suite.idPattern
import com.bettercontent.tests.suite.shaPattern
import com.bettercontent.tests.suite.suiteMapper
import java.nio.file.Files
import java.nio.file.LinkOption.NOFOLLOW_LINKS
import java.nio.file.Path
import java.security.MessageDigest
import java.time.Instant

/** Independently reviewed, exact command and expected discovered membership. Never generated by report output. */
internal data class RepositoryRunPlan(val schema: String, val status: String, val reviewer: String,
    val reviewedAt: String, val runId: String, val repository: String, val candidate: Map<String, String>,
    val reference: BoundFile, val sourceAttestation: BoundFile, val artifact: BoundFile?,
    val sourceRoot: String, val executable: String, val arguments: List<String>, val environment: Map<String, String>,
    val timeoutSeconds: Long, val inputs: Map<String, List<RepositoryInput>>,
    val reports: List<RepositoryReportPlan>,
    val runtimeToolchainFacts: Map<String, String> = emptyMap(),
    /** Explicit module roots whose generated build/run/log directories are excluded; never arbitrary basenames. */
    val generatedModuleRoots: List<String> = emptyList(),
    /** Exact reviewed Gradle command task order, distinct from observed report-producing leaf tasks. */
    val invocationTasks: List<String> = emptyList(),
    /** V3 requires explicit artifact type and test context; v2 cannot silently become runtime proof. */
    val artifactBinding: RepositoryArtifactBinding? = null,
    val executionContext: String? = null,
    /** Fresh, task-produced use witness path; a reviewed inventory alone cannot prove actual use. */
    val usageReport: String? = null,
    /** A source- and hash-inventoried producer is mandatory before a v3 source task may execute. */
    val usageReportProducer: String? = null,
    /** Shared nonshipping fixed helper, never an arbitrary repository-supplied -I script. */
    val useHarness: RepositoryInputUseHarness? = null)
internal data class RepositoryInputUseHarness(val producerSource: BoundFile, val initScript: BoundFile,
    val agentJar: BoundFile, val agentBuildReceipt: BoundFile, val javaExecutable: BoundFile,
    val allowedExternalClasspath: List<BoundFile>,
    /** Ordered exact JVM args; replace only the controller-bound agent arg with this marker. */
    val reviewedJvmArguments: List<String>,
    /** Opt-in exact securejarhandler 2.1.10 metadata-read profile; never inferred from URI text. */
    val unionHandler: BoundFile? = null, val unionAccessProfile: String? = null)
internal data class RepositoryArtifactBinding(val kind: String, val jar: BoundFile? = null,
    val clientZip: BoundFile? = null, val serverZip: BoundFile? = null)
internal data class RepositoryInput(val relativePath: String, val sha256: String, val size: Long, val executable: Boolean)
internal data class RepositoryTaskAttribution(val declarationPath: String, val declarationSha256: String,
    val reviewer: String, val reviewedAt: String, val dependencyExplanation: String)
internal data class RepositoryReportPlan(val kind: String, val task: String, val relativePath: String,
    val expectedTestIds: List<String>, val nativeRegistration: String?, val nativeLog: String?,
    val nativeOutcomes: String? = null, val reportTimezone: String = "UTC",
    val invocationTask: String? = null, val taskAttribution: RepositoryTaskAttribution? = null)
internal data class RepositoryRunReportBinding(val kind: String, val task: String, val runId: String,
    val testIds: List<String>, val startedAfter: String, val reportTimezone: String,
    val report: BoundFile, val sidecar: BoundFile, val invocationTask: String? = null)
internal data class RepositoryRunObservation(val schema: String, val status: String, val runId: String,
    val repository: String, val startedAt: String, val completedAt: String, val exitCode: Int,
    val sourceAttestation: BoundFile, val reference: BoundFile, val command: List<String>,
    val stdout: BoundFile, val stderr: BoundFile, val toolchainProbeStdout: BoundFile?,
    val toolchainProbeStderr: BoundFile?, val toolchainObserved: Map<String, String>,
    val toolchainProbeExecution: RepositoryCommandExecution?,
    val verificationExecution: RepositoryCommandExecution?, val fingerprints: Map<String, String>,
    val reports: List<RepositoryRunReportBinding>, val nativeRegistrations: List<BoundFile>, val blockers: List<String>,
    val reviewedPlan: BoundFile, val reviewedReportPlans: List<RepositoryReportPlan>,
    val artifactBinding: RepositoryArtifactBinding? = null, val executionContext: String = "source-only",
    val observedInputUse: BoundFile? = null)


/** Complete source tree inventory prevents ignored untracked files from changing the tested program. */
internal object RepositoryRunContracts {
    val groups = setOf("source", "tests", "providers", "toolchain", "configuration", "artifact")
    private val generatedDirectoryNames = setOf(".git", "build", "run", ".gradle", ".kotlin", "logs")
    private fun excludedGeneratedRoots(plan: RepositoryRunPlan): Set<String> {
        require(plan.generatedModuleRoots.distinct().size == plan.generatedModuleRoots.size) { "duplicate generated module roots" }
        val configurations = plan.inputs["configuration"].orEmpty().map { it.relativePath }.toSet()
        val modules = plan.generatedModuleRoots.map { module ->
            val path = Path.of(module)
            require(!path.isAbsolute && path.nameCount > 0 && path.normalize() == path &&
                path.none { it.toString() in setOf(".", "..") } &&
                path.first().toString() !in generatedDirectoryNames &&
                listOf("build.gradle", "build.gradle.kts").any { "$module/$it" in configurations }) {
                "generated module root requires an inventoried build declaration: $module"
            }
            module
        }
        return generatedDirectoryNames + modules.flatMap { module ->
            // A nested .git is never an implicitly ignored checkout. Only root .git is metadata.
            (generatedDirectoryNames - ".git").map { "$module/$it" }
        }
    }
    fun checkedSource(root: Path): Path {
        require(!Files.isSymbolicLink(root))
        val real = root.toRealPath()
        require(real == root.toAbsolutePath().normalize() && Files.isDirectory(real, NOFOLLOW_LINKS))
        return real
    }
    fun inventory(plan: RepositoryRunPlan, root: Path): Map<String, String> {
        require(plan.inputs.keys == groups && groups.filter { it != "providers" }.all { plan.inputs.getValue(it).isNotEmpty() }) {
            "source/test/toolchain/configuration/artifact input groups required; provider group may be explicitly empty"
        }
        val allPaths = mutableSetOf<String>()
        val actual = mutableMapOf<String, String>()
        plan.inputs.forEach { (group, entries) ->
            val ordered = entries.sortedBy { it.relativePath }
            require(ordered.map { it.relativePath }.distinct().size == ordered.size)
            ordered.forEach { entry ->
                val rel = Path.of(entry.relativePath)
                require(!rel.isAbsolute && rel.toString() == rel.normalize().toString() &&
                    rel.nameCount > 0 && rel.none { it.toString() in listOf("..", ".") } &&
                    shaPattern.matches(entry.sha256) && entry.size >= 0 && allPaths.add(rel.toString())) {
                    "duplicate/escaping/missing input: ${entry.relativePath}"
                }
                val file = root.resolve(rel)
                require(Files.isRegularFile(file, NOFOLLOW_LINKS) && !Files.isSymbolicLink(file) &&
                    file.toRealPath().startsWith(root) &&
                    (Files.getAttribute(file, "unix:nlink", NOFOLLOW_LINKS) as Number).toInt() == 1 &&
                    Files.size(file) == entry.size && Files.isExecutable(file) == entry.executable &&
                    Hashes.sha256(file) == entry.sha256) { "stale/linked $group input: $file" }
            }
            actual[group] = MessageDigest.getInstance("SHA-256").digest(suiteMapper.writeValueAsBytes(ordered))
                .joinToString("") { "%02x".format(it) }
        }
        val binding = plan.artifactBinding
        if (binding?.kind == "pack-zip-pair") {
            require(plan.inputs.getValue("artifact").size == 2 &&
                plan.inputs.getValue("artifact").map { it.sha256 }.toSet().size == 2 &&
                plan.inputs.getValue("artifact").map { it.sha256 }.toSet() ==
                    setOf(binding.clientZip?.sha256, binding.serverZip?.sha256) &&
                binding.jar == null && plan.artifact == null) {
                "pack owner requires two distinct selected client/server ZIP inputs, not a fictitious JAR"
            }
        } else require(plan.inputs.getValue("artifact").size == 1 &&
            plan.artifact != null && plan.inputs.getValue("artifact").single().sha256 == plan.artifact?.sha256 &&
            (binding == null || binding.kind == "mod-jar" && binding.jar == plan.artifact &&
                binding.clientZip == null && binding.serverZip == null)) {
            "isolated mod artifact input does not match selected packaged JAR"
        }
        if (binding != null) {
            val observed = plan.inputs.getValue("artifact").associate { entry ->
                entry.sha256 to root.resolve(entry.relativePath).toRealPath()
            }
            val references = listOfNotNull(binding.jar, binding.clientZip, binding.serverZip)
            require(references.size == observed.size && references.all { ref ->
                shaPattern.matches(ref.sha256) && Path.of(ref.path).toRealPath() == observed[ref.sha256]
            }) { "declared packaged artifacts do not identify exact isolated input files" }
        }
        // Exclude only exact generated roots at checkout or explicitly reviewed module roots;
        // src/**/build, src/**/run and other legitimate production package names remain visible.
        val excluded = excludedGeneratedRoots(plan)
        val seen = Files.walk(root).use { stream -> stream.map { path ->
            require(!Files.isSymbolicLink(path)) { "symlink in owned repository inputs: $path" }
            path
        }.filter { Files.isRegularFile(it, NOFOLLOW_LINKS) }
            .map { root.relativize(it).toString() }.filter { rel -> excluded.none { rel == it || rel.startsWith("$it/") } }.toList().toSet() }
        require(seen == allPaths) { "source checkout has missing/unmapped input files: ${seen - allPaths}; undeclared: ${allPaths - seen}" }
        return actual.toMap()
    }
    /** Reviewed invocation roots and separately declared leaf report producers.
     * An aggregate root is never itself treated as owner of a JUnit result. */
    fun requireExactTaskSelection(plan: RepositoryRunPlan): Set<String> {
        val flags = setOf("--no-daemon", "--no-build-cache", "--rerun-tasks", "--offline", "--stacktrace",
            "--info", "--no-parallel", "--console=plain", "--warning-mode=all")
        val task = Regex(":?[A-Za-z][A-Za-z0-9_-]*(?::[A-Za-z][A-Za-z0-9_-]*)*")
        val tasks = mutableListOf<String>()
        var index = 0
        while (index < plan.arguments.size) {
            val argument = plan.arguments[index]
            when {
                argument in flags -> Unit
                argument == "--max-workers" -> {
                    index++
                    require(index < plan.arguments.size && plan.arguments[index].toIntOrNull()?.let { it in 1..16 } == true) {
                        "--max-workers needs a reviewed bounded integer"
                    }
                }
                argument.startsWith("--max-workers=") -> require(argument.substringAfter('=').toIntOrNull()?.let { it in 1..16 } == true) {
                    "--max-workers needs a reviewed bounded integer"
                }
                !argument.startsWith("-") && task.matches(argument) -> tasks += argument
                else -> throw IllegalArgumentException("unsupported Gradle option or task selector: $argument")
            }
            index++
        }
        require(tasks.isNotEmpty() && tasks.distinct().size == tasks.size &&
            tasks == plan.invocationTasks && plan.reports.all { it.invocationTask in tasks } &&
            tasks.all { root -> plan.reports.any { it.invocationTask == root } }) {
            "report invocation roots must exactly equal ordered reviewed Gradle task arguments"
        }
        val leaves = plan.reports.map { it.task }
        require(leaves.all(task::matches)) {
            "report-producing leaf tasks must be explicitly declared"
        }
        return leaves.toSet()
    }

    /** Uncached actual task lines must name each leaf; skipped/cache/no-source is not a run. */
    fun requireObservedTaskExecution(stdout: String, tasks: Set<String>, invocationTasks: Set<String> = tasks) {
        require(tasks.isNotEmpty() && invocationTasks.isNotEmpty())
        val lines = stdout.lineSequence().filter { it.startsWith("> Task ") }.map { it.removePrefix("> Task ") }
            .map { it.substringBefore(' ') to it.substringAfter(' ', "") }.toList()
        invocationTasks.forEach { root ->
            val absolute = if (root.startsWith(':')) root else ":$root"
            require(lines.any { it.first == absolute && it.second != "FAILED" }) {
                "reviewed Gradle invocation root was not observed: $root"
            }
        }
        tasks.forEach { requested ->
            val absolute = if (requested.startsWith(':')) requested else ":$requested"
            require(lines.filter { it.first == absolute }.let { it.size == 1 && it.single().second.isBlank() }) {
                "reviewed leaf test task not observed as executed (or skipped/cached): $requested"
            }
        }
    }
    fun requireTaskAttribution(plan: RepositoryRunPlan) {
        plan.reports.forEach { report ->
            val relationship = report.taskAttribution
            if (report.invocationTask != report.task) {
                require(relationship != null && relationship.reviewer.isNotBlank() &&
                    runCatching { Instant.parse(relationship.reviewedAt) }.getOrNull()?.let { !it.isAfter(Instant.now()) } == true &&
                    relationship.dependencyExplanation.isNotBlank() &&
                    plan.inputs.filterKeys { it in setOf("source", "configuration", "toolchain") }.values.flatten().any {
                        it.relativePath == relationship.declarationPath && it.sha256 == relationship.declarationSha256
                    }) { "aggregate root needs independently reviewed hash-bound source task→leaf attribution" }
            } else require(relationship == null) { "direct leaf task cannot claim an unrelated aggregate attribution" }
        }
    }
    fun validate(plan: RepositoryRunPlan, runRoot: Path): Map<String, String> {
        require(plan.schema in setOf("bc.playtest_repository_run_plan.v2", "bc.playtest_repository_run_plan.v3") &&
            plan.status == "reviewed" &&
            plan.reviewer.isNotBlank() && !Instant.parse(plan.reviewedAt).isAfter(Instant.now()) &&
            idPattern.matches(plan.runId) && idPattern.matches(plan.repository) &&
            plan.candidate.keys == setOf("client_sha256", "server_sha256") &&
            plan.candidate.values.all(shaPattern::matches) &&
            plan.timeoutSeconds in 1..86_400 && plan.reports.isNotEmpty()) { "unreviewed or invalid repository command" }
        val root = checkedSource(Path.of(plan.sourceRoot))
        require(root.startsWith(runRoot.resolve("repository-inputs")) &&
            plan.executable.startsWith("./") && !plan.executable.contains("..") &&
            plan.arguments.isNotEmpty() && plan.arguments.all { it.isNotBlank() && '\u0000' !in it } &&
            plan.environment.keys.all { it in setOf("JAVA_HOME", "GRADLE_USER_HOME", "BC_CUSTOM_MOD_JAR_DIR") } &&
            plan.environment.values.all { '\u0000' !in it && '\n' !in it }) {
            "repository command escapes isolated owned inputs"
        }
        val executable = root.resolve(plan.executable.removePrefix("./"))
        require(Files.isRegularFile(executable, NOFOLLOW_LINKS) && Files.isExecutable(executable) && !Files.isSymbolicLink(executable))
        require(plan.executable == "./gradlew" &&
            plan.arguments.containsAll(listOf("--no-daemon", "--no-build-cache", "--rerun-tasks", "--console=plain")) &&
            plan.runtimeToolchainFacts.keys == setOf("gradle_version", "java_major") &&
            plan.runtimeToolchainFacts.getValue("gradle_version").matches(Regex("[0-9]+(?:\\.[0-9]+){1,3}")) &&
            plan.runtimeToolchainFacts.getValue("java_major").matches(Regex("[0-9]{1,2}"))) {
            "Gradle source verification requires uncached tasks and reviewed actual JVM/Gradle runtime facts"
        }
        if (plan.schema.endsWith("v3")) {
            require(plan.artifactBinding?.kind in setOf("mod-jar", "pack-zip-pair") &&
                plan.executionContext in setOf("source-only", "packaged-runtime") &&
                plan.usageReport?.let { relative ->
                    val path = Path.of(relative)
                    !path.isAbsolute && path.normalize() == path && path.none { it.toString() in setOf(".", "..") }
                } == true &&
                plan.useHarness?.let { harness ->
                    plan.usageReportProducer == harness.producerSource.path &&
                        harness.producerSource.path.endsWith("/scripts/playtest-repository-input-use/RepositoryInputUseAgent.java") &&
                        harness.initScript.path.endsWith("/scripts/playtest-repository-input-use/worker-init.gradle") &&
                        harness.allowedExternalClasspath.map { it.path }.distinct().size == harness.allowedExternalClasspath.size &&
                        harness.reviewedJvmArguments.size in 1..256 &&
                        harness.reviewedJvmArguments.count { it == "<controller-repository-agent>" } == 1 &&
                        harness.reviewedJvmArguments.count { it == "<controller-task-roster>" } == 1 &&
                        harness.reviewedJvmArguments.none { it.isBlank() } &&
                        ((harness.unionHandler == null && harness.unionAccessProfile == null) ||
                            (harness.unionHandler != null &&
                                harness.unionAccessProfile == "securejarhandler-2.1.10-single-base-open-v1"))
                } == true) { "v3 requires typed artifact, explicit source context and a fixed reviewed shared worker observer" }
            require(plan.executionContext == "source-only") {
                "repository Gradle source tasks cannot claim a packaged-runtime test; use separate candidate-bound campaign evidence"
            }
        } else require(plan.artifactBinding == null && plan.executionContext == null && plan.usageReport == null &&
            plan.usageReportProducer == null && plan.useHarness == null &&
            plan.repository != "better-content-modpack") { "v2 is historical mod-JAR source-only; cannot claim pack pair or runtime" }
        require(plan.reports.map { it.kind to it.task }.distinct().size == plan.reports.size)
        requireExactTaskSelection(plan)
        requireTaskAttribution(plan)
        val outputs = plan.reports.flatMap { listOfNotNull(it.relativePath, it.nativeRegistration, it.nativeLog, it.nativeOutcomes) } +
            listOfNotNull(plan.usageReport)
        require(outputs.size == outputs.distinct().size) { "report output paths must be distinct and fresh" }
        plan.reports.forEach { report ->
            require(report.kind in setOf("junit", "forge-gametest") && report.task.isNotBlank() &&
                report.expectedTestIds.isNotEmpty() && report.expectedTestIds.distinct().size == report.expectedTestIds.size &&
                report.expectedTestIds.all(String::isNotBlank) &&
                listOfNotNull(report.relativePath, report.nativeRegistration, report.nativeLog, report.nativeOutcomes).all { relative ->
                    val path = Path.of(relative)
                    !path.isAbsolute && path.normalize() == path && path.none { it.toString() == ".." }
                } && (report.kind != "forge-gametest" ||
                    report.nativeRegistration != null && report.nativeLog != null && report.nativeOutcomes != null &&
                    Path.of(report.nativeLog).parent == Path.of(report.relativePath).parent)) {
                "native registration, same-directory log, or exact test membership not authored"
            }
        }
        fun bound(ref: BoundFile): Path {
            require(shaPattern.matches(ref.sha256))
            val file = Path.of(ref.path).toRealPath()
            require(Files.isRegularFile(file, NOFOLLOW_LINKS) && !Files.isSymbolicLink(file) && Hashes.sha256(file) == ref.sha256)
            return file
        }
        if (plan.schema.endsWith("v3")) {
            val harness = requireNotNull(plan.useHarness)
            listOf(harness.producerSource, harness.initScript, harness.agentJar, harness.agentBuildReceipt,
                harness.javaExecutable).plus(harness.allowedExternalClasspath).plus(listOfNotNull(harness.unionHandler)).forEach(::bound)
            require(Files.isExecutable(Path.of(harness.javaExecutable.path)) &&
                java.util.jar.JarFile(Path.of(harness.agentJar.path).toFile()).use { jar ->
                    jar.manifest?.mainAttributes?.getValue("Premain-Class") ==
                        "com.bettercontent.playtest.repositoryinput.RepositoryInputUseAgent" &&
                        jar.getJarEntry("com/bettercontent/playtest/repositoryinput/RepositoryInputUseAgent.class") != null
                }) { "reviewed worker observer is not a JVM agent JAR with the exact fixed entry point" }
            val receipt = suiteMapper.readTree(Path.of(harness.agentBuildReceipt.path).toFile())
            require(receipt.path("schema").asText() == "bc.repository_input_use_agent_build.v1" &&
                receipt.path("producer_source_sha256").asText() == harness.producerSource.sha256 &&
                receipt.path("agent_jar_sha256").asText() == harness.agentJar.sha256 &&
                receipt.path("exit_code").asInt(-1) == 0 &&
                receipt.path("reviewer").asText().isNotBlank() &&
                runCatching { Instant.parse(receipt.path("reviewed_at").asText()) }.getOrNull()?.let {
                    !it.isAfter(Instant.now())
                } == true) {
                "shared observer JAR has no independently reviewed source/build receipt"
            }
        }
        val reference = suiteMapper.readTree(bound(plan.reference).toFile())
        require(reference.path("schema").asText() == "bc.playtest_reference.v1" &&
            plan.candidate.all { (key, value) -> reference.path("candidate").path(key).asText() == value })
        val packOwner = plan.repository == "better-content-modpack"
        val selected = plan.artifactBinding
        if (packOwner) require(plan.schema.endsWith("v3") && selected?.kind == "pack-zip-pair" &&
            selected?.clientZip?.sha256 == plan.candidate.getValue("client_sha256") &&
            selected?.serverZip?.sha256 == plan.candidate.getValue("server_sha256")) {
            "pack owner must bind exact selected client and server ZIP bytes separately"
        } else require(plan.schema.endsWith("v2") || selected?.kind == "mod-jar") {
            "mod source owner must bind its one packaged JAR, not pack ZIPs"
        }
        val ownerSource = if (packOwner) reference.path("pack_source") else
            reference.path("sources").firstOrNull { it.path("repository").asText() == plan.repository }
                ?: error("repository absent from candidate source inventory")
        require(shaPattern.matches(ownerSource.path("production_fingerprint").asText()) &&
            (if (packOwner) ownerSource.path("client_sha256").asText() == selected?.clientZip?.sha256 &&
                ownerSource.path("server_sha256").asText() == selected?.serverZip?.sha256
             else ownerSource.path("artifact_sha256").asText() == plan.artifact?.sha256)) {
            "packaged owner source fingerprint or exact artifact pair missing (build-71 bundled-input unverified)"
        }
        val attestation = suiteMapper.readTree(bound(plan.sourceAttestation).toFile())
        require(attestation.path("schema").asText() ==
            (if (packOwner) "bc.playtest_source_attestation.v2" else "bc.playtest_source_attestation.v1") &&
            attestation.path("repository").asText() == plan.repository &&
            attestation.path("reference_sha256").asText() == plan.reference.sha256 &&
            attestation.path("production_fingerprint").asText() == ownerSource.path("production_fingerprint").asText() &&
            plan.candidate.all { (key, value) -> attestation.path("candidate").path(key).asText() == value } &&
            (if (packOwner) attestation.path("client_sha256").asText() == selected?.clientZip?.sha256 &&
                attestation.path("server_sha256").asText() == selected?.serverZip?.sha256
             else attestation.path("artifact_sha256").asText() == plan.artifact?.sha256)) {
            "source-to-artifact attestation absent or stale"
        }
        if (packOwner) {
            bound(requireNotNull(selected?.clientZip)); bound(requireNotNull(selected?.serverZip))
        } else bound(requireNotNull(plan.artifact))
        val hashes = inventory(plan, root)
        val buildProof = attestation.path("build_receipt")
        require(buildProof.path("path").asText().isNotBlank() && shaPattern.matches(buildProof.path("sha256").asText())) {
            "independent source-to-artifact build receipt absent"
        }
        val buildReceipt = suiteMapper.readTree(bound(suiteMapper.treeToValue(buildProof, BoundFile::class.java)).toFile())
        require(buildReceipt.path("schema").asText() ==
            (if (packOwner) "bc.source_build_receipt.v2" else "bc.source_build_receipt.v1") &&
            buildReceipt.path("repository").asText() == plan.repository &&
            buildReceipt.path("exit_code").asInt(-1) == 0 &&
            buildReceipt.path("source_sha256").asText() == hashes.getValue("source") &&
            (if (packOwner) buildReceipt.path("client_sha256").asText() == selected?.clientZip?.sha256 &&
                buildReceipt.path("server_sha256").asText() == selected?.serverZip?.sha256
             else buildReceipt.path("artifact_sha256").asText() == plan.artifact?.sha256) &&
            buildReceipt.path("production_fingerprint").asText() == ownerSource.path("production_fingerprint").asText() &&
            buildReceipt.path("providers_sha256").asText() == hashes.getValue("providers") &&
            buildReceipt.path("toolchain_sha256").asText() == hashes.getValue("toolchain") &&
            buildReceipt.path("configuration_sha256").asText() == hashes.getValue("configuration")) {
            "source-to-packaged-JAR build provenance not independently established"
        }
        // A copied JAR plus a static hash inventory is NOT proof that this checkout produced
        // the selected candidate. Independently reviewed build receipts must contain a real
        // launched Gradle/JVM task transcript and exact owned-process cleanup evidence.
        val execution = buildReceipt.path("runtime_execution")
        val buildCommand = execution.path("command").takeIf { it.isArray }?.map { it.asText() }.orEmpty()
        require(execution.path("launcher_pid").asLong(-1) > 0 &&
            Instant.parse(execution.path("started_at").asText()) <= Instant.parse(execution.path("completed_at").asText()) &&
            execution.path("process_cleanup_complete").asBoolean(false) &&
            execution.path("surviving_pids").isArray && execution.path("surviving_pids").size() == 0 &&
            buildCommand.firstOrNull()?.endsWith("gradlew") == true &&
            buildCommand.containsAll(listOf("--no-daemon", "--no-build-cache", "--rerun-tasks")) &&
            buildCommand.any { it in (if (packOwner) setOf("package", "stageRuntimeJar") else
                setOf("reobfJar", "assemble", "build", "stageRuntimeJar")) } &&
            execution.path("reviewed_by").asText().isNotBlank()) {
            "source build receipt lacks independently reviewed runtime Gradle/JVM execution"
        }
        val buildStdout = Files.readString(bound(suiteMapper.treeToValue(execution.path("stdout"), BoundFile::class.java)))
        val buildProbe = Files.readString(bound(suiteMapper.treeToValue(execution.path("toolchain_probe_stdout"), BoundFile::class.java)))
        require(buildStdout.contains("BUILD SUCCESSFUL") &&
            Regex("(?m)^Gradle [0-9]+(?:\\.[0-9]+){1,3}\\s*$").containsMatchIn(buildProbe) &&
            Regex("(?m)^(?:Launcher JVM|JVM):\\s*(?:[a-zA-Z ]*)?\\d+").containsMatchIn(buildProbe)) {
            "source build receipt lacks observed successful build and launched JVM/Gradle probe logs"
        }
        require(hashes.getValue("artifact") == attestation.path("artifact_inputs_sha256").asText() &&
            hashes.getValue("source") == attestation.path("source_sha256").asText() &&
            hashes.getValue("tests") == attestation.path("tests_sha256").asText() &&
            hashes.getValue("providers") == attestation.path("providers_sha256").asText() &&
            hashes.getValue("toolchain") == attestation.path("toolchain_sha256").asText() &&
            hashes.getValue("configuration") == attestation.path("configuration_sha256").asText()) {
            "source/tests/providers/toolchain/config/artifact inputs are not bound to selected source attestation"
        }
        return hashes
    }
}
